input.command:
S=/private/tmp/claude-501/-Users-Apple-neatlog/4836bf52-cf6c-452b-98b0-b0deb7acb0c9/scratchpad; rm -rf $S/g && mkdir -p $S/g/src $S/g/test && cd $S/g && git init -q && cat > package.json <<'E'
{"name":"m0-graph","version":"1.0.0","private":true,"scripts":{"test":"node --test test/"},"dependencies":{"chalk":"4.1.2"}}
E
cat > src/log.js <<'E'
const chalk = require('chalk');
function formatError(msg) { return chalk.red(msg); }
function formatOk(msg) { return chalk.green(msg); }
module.exports = { formatError, formatOk };
E
cat > src/report.js <<'E'
const { formatError, formatOk } = require('./log');
function report(results) { return results.map(r => (r.ok ? formatOk(r.name) : formatError(r.name))).join('\n'); }
module.exports = { report };
E
cat > src/math.js <<'E'
function add(a, b) { return a + b; }
module.exports = { add };
E
cat > test/report.test.js <<'E'
const test = require('node:test'); const assert = require('node:assert');
const { report } = require('../src/report');
test('report lists names', () => { assert.match(report([{ ok: true, name: 'a' }]), /a/); });
E
git add -A && git -c user.email=a@b.c -c user.name=m0 commit -qm init
echo "---- doctor"; entire graph doctor 2>&1 | head -25
echo "---- search"; entire graph search --repo . --profile full --query "code that uses chalk to colour output" 2>&1 | head -30
echo "---- impact formatError"; entire graph impact --repo . --symbol formatError 2>&1 | head -40
echo "---- neighbors"; entire graph neighbors --repo . --symbol formatError --relation CALLS --direction in 2>&1 | head -20
echo "---- imports edges"; entire graph edges --repo . 2>&1 | grep -i -m8 -E 'IMPORT|chalk'
echo "---- json?"; entire graph impact --repo . --symbol formatError --json 2>&1 | head -c 1500

